`include "KF8259_Common_Package.svh"
module proof(input [2:0] rotation,
 input [7:0] requests, service, highest, mask, special_mask, eoi,
 input fully_nested, latch_service, output ok);
wire [7:0] irq;
KF8259_Priority_Resolver dut(rotation, mask, special_mask,
 fully_nested, highest, requests, service, irq);
wire [7:0] remaining = service & ~eoi & ~special_mask;
wire [7:0] pending = irq & ~special_mask;
wire [7:0] original = KF8259_Common_Package::resolve_rotated_priority(
 remaining | (latch_service ? pending : 8'b0), rotation);
wire [7:0] candidate = latch_service && |pending ? pending :
 KF8259_Common_Package::resolve_rotated_priority(remaining, rotation);
wire valid = (highest & (highest - 8'b1)) == 0;
assign ok = original == candidate;
endmodule

